'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,scans=[],inventory=[],current=null,stream=null,running=false,generation=0,reader=null,detector=null,timer=null,cameras=[],torchOn=false,audio=null,lastSeen='',lastDetected=0,lastSaved=new Map(),noticeTimer,editingBarcode='';
const defaults={sound:true,vibration:true,continuous:false,duplicates:true,preferred:'',theme:'system'};let settings={...defaults};const fields=[['barcode','Barcode'],['itemName','Item Name'],['assetTag','Asset Tag'],['serialNumber','Serial Number'],['category','Category'],['description','Description'],['location','Location'],['assignedTo','Assigned To'],['quantity','Quantity'],['notes','Notes']];
function notify(message,persistent=false){clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').hidden=false;if(!persistent)noticeTimer=setTimeout(()=>$('#notice').hidden=true,5500)}
function openDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('smart-barcode-scanner',1);request.onupgradeneeded=()=>{for(const name of ['scans','inventory','settings'])request.result.createObjectStore(name,{keyPath:name==='inventory'?'barcode':'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>notify('Close other tabs of this app, then reload to open your records.',true)})}
function all(store){return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function mutate(store,action,value){return new Promise((resolve,reject)=>{if(!db)return reject(new Error('Storage unavailable'));const tx=db.transaction(store,'readwrite');const object=tx.objectStore(store);action==='clear'?object.clear():object[action](value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function theme(){document.documentElement.dataset.theme=settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):settings.theme}
function setPage(page){if(page!=='scanner')stopCamera();document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==page);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.page===page));render();window.scrollTo({top:0,behavior:'instant'})}
function matching(row,query){const item=inventory.find(i=>i.barcode===row.barcode)||row;return [row.barcode,item.itemName,item.assetTag,item.serialNumber].some(v=>String(v||'').toLowerCase().includes(query.toLowerCase()))}
function stats(){return `<div><b>${scans.filter(s=>new Date(s.at).toDateString()===new Date().toDateString()).length}</b><span>Scans Today</span></div><div><b>${scans.length}</b><span>Total Scans</span></div><div><b>${new Set(scans.map(s=>s.barcode)).size}</b><span>Unique Barcodes</span></div>`}
function empty(isInventory=false){return `<div class="empty"><b>${isInventory?'No saved items yet.':'No barcodes scanned yet.'}</b><p>${isInventory?'Scan or enter a barcode, then add item details.':'Tap Start Scanner to scan your first barcode.'}</p></div>`}
function rowHTML(row,isInventory=false,compact=false){const item=inventory.find(i=>i.barcode===row.barcode)||{},id=esc(row.id||row.barcode);return `<div class="row"><div><b class="mono">${esc(row.barcode)}</b>${item.itemName?`<p>${esc(item.itemName)}</p>`:''}<p>${isInventory?esc([item.assetTag,item.location,`Quantity: ${item.quantity??1}`].filter(Boolean).join(' · ')):`${esc(row.format)} · ${esc(row.source)}<br>${esc(new Date(row.at).toLocaleDateString())} · ${esc(new Date(row.at).toLocaleTimeString())}`}</p></div>${compact?'':`<div class="actions"><button data-copy="${esc(row.barcode)}">Copy</button><button data-edit="${esc(row.barcode)}">${isInventory?'Edit':'Details'}</button><button data-rescan="${esc(row.barcode)}">Rescan</button>${isInventory?'':`<button data-delete="${id}" class="danger">Delete</button>`}</div>`}</div>`}
function render(){scans.sort((a,b)=>b.at-a.at);$('#dashboard-stats').innerHTML=stats();$('#dashboard-items').textContent=inventory.length;$('#dashboard-recent').innerHTML=scans.slice(0,5).map(r=>rowHTML(r,false,true)).join('')||empty();$('#scanner-stats').innerHTML=stats();$('#history-stats').innerHTML=stats();$('#recent').innerHTML=scans.slice(0,4).map(r=>rowHTML(r,false,true)).join('')||empty();const history=scans.filter(r=>matching(r,$('#history-search').value));$('#history-list').innerHTML=history.map(r=>rowHTML(r)).join('')||(scans.length?'<div class="empty">No matching scans.</div>':empty());const items=inventory.filter(i=>matching(i,$('#inventory-search').value));$('#inventory-list').innerHTML=items.map(i=>rowHTML(i,true)).join('')||(inventory.length?'<div class="empty">No matching items.</div>':empty(true));$('#inventory-count').textContent=`${inventory.length} saved ${inventory.length===1?'item':'items'}`;$('#export').disabled=!scans.length;$('#clear').disabled=!scans.length}
function showResult(scan){current=scan;const item=inventory.find(i=>i.barcode===scan.barcode);$('#result').hidden=false;$('#result').innerHTML=`<h2>SCAN SUCCESSFUL</h2><p class="mono">${esc(scan.barcode)}</p><dl><div><dt>Format</dt><dd>${esc(scan.format)}</dd></div><div><dt>Date</dt><dd>${esc(new Date(scan.at).toLocaleDateString())}</dd></div><div><dt>Time</dt><dd>${esc(new Date(scan.at).toLocaleTimeString())}</dd></div></dl><div class="toolbar"><button data-copy="${esc(scan.barcode)}">Copy</button><button id="scan-again">Scan Again</button><button data-edit="${esc(scan.barcode)}">Add Details</button></div>${item?`<div class="duplicate"><strong>Barcode already exists</strong><p>${esc(item.itemName||item.barcode)}${item.assetTag?` · ${esc(item.assetTag)}`:''}${item.location?` · ${esc(item.location)}`:''}</p><div class="toolbar"><button data-view="${esc(item.barcode)}">View Existing Record</button><button data-edit="${esc(item.barcode)}">Update Record</button><button id="scan-another">Scan Another</button></div></div>`:''}`}
async function record(barcode,format,source){const scan={id:crypto.randomUUID(),barcode,format,source,at:Date.now()};try{await mutate('scans','put',scan);scans.unshift(scan);showResult(scan);render();return true}catch{notify('The scan could not be saved. Check browser storage permissions, then try again.',true);return false}}
function feedback(){if(settings.vibration&&navigator.vibrate)navigator.vibrate(60);if(settings.sound&&audio){try{const osc=audio.createOscillator(),gain=audio.createGain();osc.connect(gain);gain.connect(audio.destination);osc.frequency.value=1100;gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);osc.start();osc.stop(audio.currentTime+.12)}catch{}}$('#camera').classList.add('success');setTimeout(()=>$('#camera').classList.remove('success'),450)}
function cameraUI(active){$('#idle').hidden=active;$('.guide').hidden=!active;$('#frame-tip').hidden=!active;$('#start').hidden=active;$('#stop').hidden=!active;$('#camera-state').textContent=active?'Scanning':'Camera off';$('#switch').hidden=!active||cameras.length<2;$('#camera-select').hidden=!active||cameras.length<2}
function stopCamera(){generation++;running=false;clearTimeout(timer);if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#video').srcObject=null;$('#torch').hidden=true;torchOn=false;cameraUI(false)}
async function listCameras(){try{cameras=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');const options=cameras.map((c,i)=>`<option value="${esc(c.deviceId)}">${esc(c.label||`Camera ${i+1}`)}</option>`).join('');$('#camera-select').innerHTML=options;$('#preferred').innerHTML='<option value="">Rear camera (automatic)</option>'+options;$('#preferred').value=settings.preferred;const selected=stream?.getVideoTracks()[0]?.getSettings().deviceId;if(selected)$('#camera-select').value=selected}catch{}}
const nativeFormats=['code_128','code_39','code_93','ean_13','ean_8','upc_a','upc_e','itf','codabar','data_matrix','qr_code'];
async function engines(){reader=window.ZXing?new ZXing.BrowserMultiFormatReader():null;detector=null;if('BarcodeDetector' in window){try{const supported=await BarcodeDetector.getSupportedFormats();const formats=nativeFormats.filter(f=>supported.includes(f));if(formats.length)detector=new BarcodeDetector({formats})}catch{}}if(!reader&&!detector)throw {name:'ScannerUnavailable'}}
function friendly(error){return ({NotAllowedError:'Camera access was blocked. Please allow camera permission in your browser settings or enter the barcode manually.',NotFoundError:'No camera was found. Connect a camera or enter the barcode manually.',NotReadableError:'The camera is unavailable or already being used. Close other camera apps and try again.',OverconstrainedError:'This camera could not be opened. Choose another camera or use manual entry.',ScannerUnavailable:'The scanner could not start. Reload this page or enter the barcode manually.'})[error.name]||'The camera could not start. Please try again or enter the barcode manually.'}
async function startCamera(device){stopCamera();if(!window.isSecureContext){notify('Camera scanning requires a secure HTTPS connection. Open the secure site link or enter a barcode manually.',true);return}if(!navigator.mediaDevices?.getUserMedia){notify('This browser does not support camera access. Use a recent browser or enter the barcode manually.',true);return}$('#start').disabled=true;$('#start').textContent='Starting camera…';const token=generation;try{if(settings.sound){audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{})}await engines();const videoConstraints={width:{ideal:1280},height:{ideal:720},...(device||settings.preferred?{deviceId:{exact:device||settings.preferred}}:{facingMode:{ideal:'environment'}})};let acquired;try{acquired=await navigator.mediaDevices.getUserMedia({audio:false,video:videoConstraints})}catch(error){if(error.name==='OverconstrainedError'&&!device)acquired=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'}}});else throw error}if(token!==generation){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;$('#video').srcObject=stream;await $('#video').play();if(token!==generation)return;running=true;lastSeen='';lastDetected=0;await listCameras();cameraUI(true);const track=stream.getVideoTracks()[0];$('#torch').hidden=!track.getCapabilities?.().torch;$('#notice').hidden=true;scanLoop(token);setTimeout(()=>{if(running&&token===generation&&!current)notify('No barcode recognized yet. Improve the lighting and bring the full code into focus.')},12000)}catch(error){if(token===generation){stopCamera();notify(friendly(error),true);if(error.name==='NotAllowedError')$('#start').textContent='Allow Camera Access'}}finally{$('#start').disabled=false;if($('#start').textContent==='Starting camera…')$('#start').textContent='Start Scanner'}}
async function decodeFrame(){if($('#video').readyState<2)return null;if(detector){try{const hits=await detector.detect($('#video'));if(hits.length)return {barcode:hits[0].rawValue,format:hits[0].format.replaceAll('_',' ').toUpperCase()}}catch{detector=null}}if(reader){try{const result=reader.decode($('#video'));return {barcode:result.getText(),format:ZXing.BarcodeFormat[result.getBarcodeFormat()].replaceAll('_',' ')}}catch(error){if(!['NotFoundException','ChecksumException','FormatException'].includes(error.name)&&!detector){/* Frames without a valid code are expected. */}}}return null}
async function scanLoop(token){if(!running||generation!==token)return;const found=await decodeFrame();if(!running||generation!==token)return;const now=Date.now();if(found&&found.barcode){const sameInView=lastSeen===found.barcode&&now-lastDetected<900;lastSeen=found.barcode;lastDetected=now;const cooldown=now-(lastSaved.get(found.barcode)||0)<2000;if(!(settings.duplicates&&(sameInView||cooldown))){lastSaved.set(found.barcode,now);const saved=await record(found.barcode,found.format,'Camera');if(saved){feedback();if(!settings.continuous){stopCamera();return}notify(`Scanned: ${found.barcode}`)}}}if(running&&generation===token)timer=setTimeout(()=>scanLoop(token),150)}
function details(barcode){editingBarcode=barcode;const item=inventory.find(i=>i.barcode===barcode)||{barcode,quantity:1};$('#details-fields').innerHTML=fields.map(([key,label])=>`<label class="${['description','notes'].includes(key)?'wide':''}">${label}${['description','notes'].includes(key)?`<textarea name="${key}" rows="2" maxlength="4096">${esc(item[key]||'')}</textarea>`:`<input name="${key}" value="${esc(item[key]??'')}" ${key==='barcode'?'readonly required':''} ${key==='quantity'?'type="number" min="0" step="1" required':'maxlength="4096"'}>`}</label>`).join('');$('#details-dialog').showModal()}
async function copy(value){try{await navigator.clipboard.writeText(value);notify('Barcode copied.')}catch{const input=document.createElement('textarea');input.value=value;document.body.append(input);input.select();let ok=false;try{ok=document.execCommand('copy')}catch{}input.remove();notify(ok?'Barcode copied.':'Copy is unavailable. Select the barcode text and copy it manually.')}}
function csvCell(value){const s=String(value??'');return '"'+(/^[=+\-@\t\r]/.test(s)?"'"+s:s).replaceAll('"','""')+'"'}
function exportCSV(){const columns=['Barcode','Format','Item Name','Asset Tag','Serial Number','Category','Description','Location','Assigned To','Quantity','Notes','Scan Source','Date','Time'];const rows=scans.map(scan=>{const item=inventory.find(i=>i.barcode===scan.barcode)||{};return [scan.barcode,scan.format,...fields.slice(1).map(([k])=>item[k]??''),scan.source,new Date(scan.at).toLocaleDateString(),new Date(scan.at).toLocaleTimeString()]});const blob=new Blob(['\uFEFF'+[columns,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`barcode-scans-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported. In Excel, import Barcode as Text to preserve leading zeros.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)setPage(b.dataset.page);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.dataset.copy)copy(b.dataset.copy);if(b.dataset.edit)details(b.dataset.edit);if(b.dataset.view){setPage('inventory');$('#inventory-search').value=b.dataset.view;render()}if(b.dataset.rescan||['scan-again','scan-another'].includes(b.id)){setPage('scanner');startCamera()}if(b.dataset.delete){try{await mutate('scans','delete',b.dataset.delete);scans=scans.filter(s=>s.id!==b.dataset.delete);render();notify('Scan deleted.')}catch{notify('The scan could not be deleted. Try again.')}}});
$('#start').onclick=()=>startCamera();$('#stop').onclick=()=>stopCamera();$('#switch').onclick=()=>{const index=cameras.findIndex(c=>c.deviceId===$('#camera-select').value);startCamera(cameras[(index+1)%cameras.length].deviceId)};$('#camera-select').onchange=e=>startCamera(e.target.value);$('#torch').onclick=async()=>{try{const next=!torchOn;await stream.getVideoTracks()[0].applyConstraints({advanced:[{torch:next}]});torchOn=next;$('#torch').textContent=next?'Flashlight off':'Flashlight'}catch{notify('Flashlight is unavailable on this camera.');$('#torch').hidden=true}};
$('#manual-open').onclick=()=>{stopCamera();$('#manual-dialog').showModal()};$('#manual-form').onsubmit=async e=>{e.preventDefault();const value=new FormData(e.target).get('barcode').trim();if(!value){notify('Enter a barcode value.');return}if(await record(value,'Unknown / Manual','Manual')){$('#manual-dialog').close();e.target.reset();setPage('scanner')}};
$('#details-form').onsubmit=async e=>{e.preventDefault();const item=Object.fromEntries(new FormData(e.target));item.barcode=editingBarcode;item.quantity=Number(item.quantity);try{await mutate('inventory','put',item);inventory=inventory.filter(i=>i.barcode!==item.barcode);inventory.unshift(item);$('#details-dialog').close();render();if(current)showResult(current);notify('Inventory record saved.')}catch{notify('This record could not be saved. Your entered details are still available. Try again.',true)}};
$('#history-search').oninput=render;$('#inventory-search').oninput=render;$('#export').onclick=exportCSV;$('#clear').onclick=()=>$('#confirm-dialog').showModal();$('#confirm-clear').onclick=async()=>{try{await mutate('scans','clear');scans=[];current=null;$('#result').hidden=true;$('#confirm-dialog').close();render();notify('Scan history cleared.')}catch{notify('History could not be cleared. Try again.')}};
for(const key of Object.keys(defaults))$('#'+key).onchange=async e=>{settings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;theme();try{await mutate('settings','put',{...settings,id:'preferences'})}catch{notify('Settings could not be saved.')}};
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopCamera()});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);
(async()=>{try{db=await openDB();[scans,inventory]=await Promise.all([all('scans'),all('inventory')]);const saved=await all('settings');if(saved.length)settings={...defaults,...saved[0]};db.onversionchange=()=>{db.close();notify('Reload to use the updated local storage.',true)}}catch{notify('Local storage is unavailable. Enable browser storage and reload before saving scans.',true)}for(const key of Object.keys(defaults)){const e=$('#'+key);e.type==='checkbox'?e.checked=settings[key]:e.value=settings[key]}theme();render();if(navigator.mediaDevices?.enumerateDevices)listCameras()})();

async function checkSession(){try{const response=await fetch('/api/auth/me',{cache:'no-store',credentials:'same-origin'});if(response.status===401){stopCamera();location.replace('/login');return}if(response.ok){const result=await response.json();$('#account-email').textContent=result.user.email}}catch{notify('Connection unavailable. Check your connection before continuing.')}}
$('#logout').onclick=async()=>{stopCamera();try{const response=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});if(!response.ok)throw Error();location.replace('/login')}catch{notify('Unable to sign out. Please retry.')}};
window.addEventListener('pageshow',checkSession);setInterval(checkSession,60000);
